import 'dart:io' as io;

import 'package:args/args.dart';
import 'package:path/path.dart' as p;

import 'deps_file.dart';
import 'deps_outputs.dart';

/// The label used in the "generated by" banner of the output files.
const String generatorLabel = 'engine/src/flutter/tools/bazel_tools/bin/gen_deps.dart';

/// Where `deps.lock.bzl` lives, relative to the repository root.
const String defaultDepsLockPath = 'engine/src/flutter/build/bazel/deps.lock.bzl';

/// Where `.bazelignore` lives, relative to the repository root.
const String defaultBazelignorePath = '.bazelignore';

/// Finds the repository root (the directory containing `DEPS` and
/// `engine/src/flutter`) by walking up from [start], which defaults to the
/// current directory.
///
/// Returns `null` if [start] is not inside a checkout.
String? findRepositoryRoot([String? start]) {
  String directory = p.canonicalize(start ?? io.Directory.current.path);
  while (true) {
    if (io.File(p.join(directory, 'DEPS')).existsSync() &&
        io.Directory(p.join(directory, 'engine', 'src', 'flutter')).existsSync()) {
      return directory;
    }
    final String parent = p.dirname(directory);
    if (parent == directory) {
      return null;
    }
    directory = parent;
  }
}

/// Generates (or checks) the Bazel files derived from `DEPS`.
final class GenDepsCommand {
  /// Creates the command from parsed command-line [arguments].
  GenDepsCommand._({
    required this.repoRoot,
    required this.check,
    required this.verbose,
    required io.IOSink stdout,
    required io.IOSink stderr,
  }) : _stdout = stdout,
       _stderr = stderr;

  /// Parses [arguments] and creates the command.
  ///
  /// Prints usage and returns `null` when `--help` is requested or the
  /// arguments are invalid.
  static GenDepsCommand? fromCommandLine(
    List<String> arguments, {
    io.IOSink? stdout,
    io.IOSink? stderr,
    String? workingDirectory,
  }) {
    final io.IOSink out = stdout ?? io.stdout;
    final io.IOSink err = stderr ?? io.stderr;
    final ArgResults results;
    try {
      results = argParser.parse(arguments);
    } on FormatException catch (e) {
      err
        ..writeln(e.message)
        ..writeln()
        ..writeln(usage);
      return null;
    }
    if (results.flag('help')) {
      out.writeln(usage);
      return null;
    }
    final String? repoRootArgument = results.option('repo-root');
    final String? repoRoot = repoRootArgument != null
        ? p.canonicalize(repoRootArgument)
        : findRepositoryRoot(workingDirectory);
    if (repoRoot == null) {
      err.writeln(
        'Could not find the repository root (the directory containing DEPS) '
        'from the current directory; pass --repo-root.',
      );
      return null;
    }
    return GenDepsCommand._(
      repoRoot: repoRoot,
      check: results.flag('check'),
      verbose: results.flag('verbose'),
      stdout: out,
      stderr: err,
    );
  }

  /// The command-line options.
  static final ArgParser argParser = ArgParser()
    ..addFlag('help', abbr: 'h', negatable: false, help: 'Print this help.')
    ..addFlag(
      'check',
      negatable: false,
      help:
          'Do not write anything; exit with status 1 if the generated files '
          'are missing or out of date (for presubmit).',
    )
    ..addFlag('verbose', abbr: 'v', negatable: false, help: 'Print each file written.')
    ..addOption(
      'repo-root',
      help:
          'The repository root (the directory containing DEPS). Defaults to '
          'the checkout the current directory is in.',
      valueHelp: 'path',
    );

  /// Usage text.
  static String get usage =>
      'Usage: dart bin/gen_deps.dart [options]\n'
      '\n'
      'Generates the Bazel files derived from DEPS:\n'
      '  $defaultDepsLockPath\n'
      '  $defaultBazelignorePath\n'
      '\n'
      '${argParser.usage}';

  /// The repository root (the directory containing `DEPS`).
  final String repoRoot;

  /// Whether to verify the files instead of writing them.
  final bool check;

  /// Whether to print each file written.
  final bool verbose;

  final io.IOSink _stdout;
  final io.IOSink _stderr;

  /// Runs the command and returns the process exit code.
  Future<int> run() async {
    final depsFile = io.File(p.join(repoRoot, 'DEPS'));
    if (!depsFile.existsSync()) {
      _stderr.writeln('No DEPS file found at ${depsFile.path}.');
      return 1;
    }
    final DepsFile deps;
    try {
      deps = DepsFile.parse(await depsFile.readAsString(), fileName: depsFile.path);
    } on DepsFormatException catch (e) {
      _stderr.writeln('Failed to parse DEPS: $e');
      return 1;
    }

    final outputs = <String, String>{
      defaultDepsLockPath: generateDepsLock(deps, generator: generatorLabel),
      defaultBazelignorePath: generateBazelignore(deps, generator: generatorLabel),
    };

    var stale = false;
    for (final MapEntry<String, String> output in outputs.entries) {
      final file = io.File(p.join(repoRoot, output.key));
      final String? existing = file.existsSync() ? await file.readAsString() : null;
      if (existing == output.value) {
        if (verbose) {
          _stdout.writeln('Up to date: ${output.key}');
        }
        continue;
      }
      if (check) {
        stale = true;
        _stderr.writeln(existing == null ? 'Missing: ${output.key}' : 'Out of date: ${output.key}');
        continue;
      }
      file.parent.createSync(recursive: true);
      await file.writeAsString(output.value);
      if (verbose) {
        _stdout.writeln('Wrote: ${output.key}');
      }
    }
    if (stale) {
      _stderr.writeln('Run `dart $generatorLabel` from the repository root and commit the result.');
      return 1;
    }
    return 0;
  }
}
